/* --- 算法凝视-夜晚加载中 (Algorithm Gaze - Night Loading) v2.1 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.--- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');
@import url("https://fontsapi.zeoseven.com/183/main/result.css"); /* 全局：极影毁片辉宋 Bold */
@import url("https://fontsapi.zeoseven.com/156/main/result.css"); /* 引用：平方时光体 */
@import url("https://fontsapi.zeoseven.com/970/main/result.css"); /* 标题：XuanZongTi */
@import url("https://fontsapi.zeoseven.com/5/main/result.css"); /* 代码：Hangeuljaemin4.0 */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #121212;
    --panel-bg-color: rgba(25, 25, 25, 0.85);
    --panel-bg-hover: rgba(40, 40, 40, 0.95);
    --card-bg: rgba(30, 30, 30, 0.9);
    --input-bg: rgba(20, 20, 20, 0.9);
    --text-main: #E6E6E6;
    --text-subtle: #B08484;
    --border-color: rgba(139, 0, 0, 0.4);
    --accent-color: #8B0000;
    --selected-color: #4A0000;
    --font-english: 'VT323', monospace; 
    --font-main: "极影毁片辉宋 Bold", var(--font-english);
    --font-quote: "平方时光体", var(--font-english);
    --font-code: "Hangeuljaemin4.0", monospace;
    --font-title: "XuanZongTi", var(--font-english);
    --border-radius: 4px;
}

/* --- 3. 全局样式 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/0jlI/4578X2298/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D5064664199991360891%26skey%3D%40crypt_5a237c93_d042088f617635782c79a9e8ba4d1d73%26mmweb_appid%3Dwx_webfilehelper.jpg/webp');
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--text-main); font-weight: normal; }

/* --- 4. 顶部导航栏 & 挂件 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border: none; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.3s ease; filter: grayscale(100%); }
.drawer-icon.fa-fw:hover { transform: scale(1.1); }
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/izmZ/1963X2060/2026-03-04_172119.png/webp'); }
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/OrWu/1858X1794/2026-03-04_172047.png/webp'); }
.drawer-content { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/0jlI/4578X2298/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D5064664199991360891%26skey%3D%40crypt_5a237c93_d042088f617635782c79a9e8ba4d1d73%26mmweb_appid%3Dwx_webfilehelper.jpg/webp'); background-size: cover; background-position: center; border: none !important; border-radius: var(--border-radius); }

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { pointer-events: auto; width: 90% !important; max-width: 800px !important; margin: 0 auto !important; border-radius: 25px !important; background-color: var(--input-bg) !important; padding: 10px 15px !important; backdrop-filter: blur(10px) !important; -webkit-backdrop-filter: blur(10px) !important; transition: all 0.5s ease !important; position: relative; border: 1px solid rgba(255, 255, 255, 0.1) !important; border-style: solid !important; }
#send_form:hover { transform: translateY(-5px) !important; background-color: var(--panel-bg-hover) !important; }
#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { content: 'Input command..._'; color: #AAA; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-family: var(--font-english); font-size: 0.5em; pointer-events: none; z-index: 10; white-space: nowrap; letter-spacing: 3px; }
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; filter: grayscale(100%); }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.1); }
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/UCoy/1728X1925/2026-03-04_172141.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/i742/1287X1728/2026-03-04_180651.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/qrmc/1168X1958/2026-03-04_172028.png/webp'); }
#ai_retry_button, #auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/UCoy/1728X1925/2026-03-04_172141.png/webp'); }

/* --- 6. 核心：消息框布局与样式 --- */
@keyframes blink-alert { 50% { opacity: 0.6; } }
.mes { 
    display: flex; flex-direction: column; 
    padding: 34px 6px 6px 6px !important; 
    margin: 45px auto 40px !important; 
    width: 85%; max-width: 700px; 
    background: rgba(18, 18, 18, 0.6) !important; 
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important; 
    border-style: solid !important; 
    border-radius: 6px !important; 
    overflow: visible !important; 
    position: relative; 
    outline: 2px solid rgba(255, 255, 255, 0.1) !important;
    outline-offset: 3px;
}

/* 模拟窗口标题栏 */
.mes::before {
    content: 'INCOMING_TRANSMISSION';
    position: absolute;
    top: 0; left: 0;
    width: 100%;
    height: 28px;
    background-color: rgba(30, 30, 30, 0.8);
    border-bottom: 1px solid rgba(255, 255, 255, 0.15) !important;
    border-style: solid !important;
    border-radius: 6px 6px 0 0;
    display: flex;
    align-items: center;
    padding-left: 15px;
    font-family: var(--font-english);
    color: #ccc;
    font-size: 14px;
    letter-spacing: 2px;
    z-index: 10;
}

/* 模拟窗口控制按钮 */
.mes::after {
    content: '_ ☐ X';
    position: absolute;
    top: 0;
    right: 15px;
    height: 28px;
    display: flex;
    align-items: center;
    font-family: var(--font-english);
    color: #ccc;
    font-size: 16px;
    letter-spacing: 8px;
    z-index: 11;
}

/* 模拟系统警报/每日推送 */
.mes .mes_block::before {
    content: 'System Alert: Cognitive Sync Recommended';
    position: absolute;
    bottom: 15px; right: 15px;
    background-color: rgba(139, 0, 0, 0.5);
    border: 1px solid rgba(255, 100, 100, 0.5) !important;
    border-style: solid !important;
    color: #fdd;
    font-family: var(--font-english);
    font-size: 12px;
    padding: 4px 8px;
    border-radius: 4px;
    z-index: 100;
    animation: blink-alert 2s infinite ease-in-out;
}

.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    width: 100%;
    background-size: cover; background-position: center;
    position: relative; z-index: 5;
    height: 120px !important; 
    min-height: 120px !important;
    overflow: visible !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
    border-style: solid !important;
}
.mes[is_user="true"] .mesAvatarWrapper, .mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/Q9Fn/4578X2298/%E6%9C%AA%E6%A0%87%E9%A2%98-2.png/webp'); }

.mes .avatar {
    position: absolute;
    top: 60px; 
    left: 40px; 
    width: 100px !important; height: 100px !important; 
    background-color: transparent !important;
    padding: 0 !important; 
    border: 3px solid rgba(255, 255, 255, 0.6) !important;
    border-style: solid !important;
    z-index: 30; 
    border-radius: 50% !important; 
    box-shadow: none !important;
}
.mes[is_user="true"] .avatar { left: 40px; right: auto; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 50% !important; border: none !important; image-rendering: -webkit-optimize-contrast; image-rendering: crisp-edges; filter: grayscale(20%); }
.mes .mesAvatarWrapper::after { display: none; }

.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 50px 30px 40px 30px !important; margin-top: 0 !important; position: relative; border: none !important; overflow: visible !important; min-height: 100px !important; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 10px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { content: "// ALGORITHM.TRACE //"; font-family: var(--font-english); font-size: 14px !important; color: var(--accent-color); visibility: visible; letter-spacing: 2px; }
.mes_reasoning { border-left: 2px solid var(--accent-color) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); }
.mes .mes_text { line-height: 1.9; color: var(--text-main); font-size: 15px; }

/* --- 黑白红排版与文字特效系统 --- */
.mes_text h1 { font-family: var(--font-title); color: var(--accent-color); font-size: 1.7em; text-align: center; position: relative; padding-bottom: 15px; margin: 30px 0 20px 0; border-bottom: 1px solid rgba(139, 0, 0, 0.3) !important; font-weight: normal; letter-spacing: 3px; }
.mes_text h1::after { content: '>_'; position: absolute; bottom: -11px; left: 50%; transform: translateX(-50%); color: var(--text-main); background: rgba(18, 18, 18, 0.6); padding: 0 12px; font-family: var(--font-english); font-size: 1.1em; }
.mes_text h2 { font-family: var(--font-title); color: var(--text-main); font-size: 1.4em; padding: 6px 0 6px 15px; border-left: 3px solid var(--accent-color) !important; margin: 25px 0 15px 0; background: linear-gradient(to right, rgba(139, 0, 0, 0.15) 0%, transparent 100%); border-radius: 0 8px 8px 0; font-weight: normal; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--italics_text_color); background: rgba(139,0,0,0.15); padding: 2px 6px; border-radius: 4px; margin: 0 2px; }
.mes_text strong, .mes_text b { font-family: var(--font-title); color: var(--text-main); font-weight: normal; border-bottom: 1px solid var(--accent-color) !important; padding: 0 2px; }
.mes_text blockquote { background-color: rgba(0, 0, 0, 0.2); border: none !important; border-left: 3px solid rgba(255, 255, 255, 0.5) !important; padding: 12px 18px; border-radius: 0 8px 8px 0; margin: 18px 0; font-family: var(--font-quote); color: var(--quote_text_color); position: relative; }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code); background-color: rgba(0, 0, 0, 0.3) !important; color: var(--text-main) !important; padding: 2px 6px; border-radius: 4px; border: none !important; }

/* --- 用户名、时间戳与编辑按钮 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name { display: flex !important; position: absolute; top: 20px !important; left: 150px !important; right: 150px !important; width: auto !important; align-items: flex-start !important; background: transparent !important; border: none !important; z-index: 100; transform: none !important; padding: 0; }
.mes[is_user="false"] .ch_name { justify-content: flex-start !important; }
.mes[is_user="true"] .ch_name { justify-content: flex-start !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; flex-wrap: wrap !important; }
.mes .ch_name .name_text { font-family: var(--font-english); font-size: 16px !important; color: var(--text-main) !important; letter-spacing: 1px; }
.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: #999 !important; font-size: 12px !important; line-height: 1 !important; transform: none !important; }
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; position: static !important; opacity: 0.5; transition: opacity 0.3s ease; pointer-events: auto !important; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(40, 40, 40, 0.7) !important; backdrop-filter: blur(4px); color: #ccc !important; padding: 6px !important; border-radius: 6px !important; cursor: pointer; transition: all 0.2s ease; font-size: 14px !important; height: auto !important; width: auto !important; line-height: 1 !important; border: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-color) !important; color: white !important; transform: scale(1.1); }

/* 打字提示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/i742/1287X1728/2026-03-04_180651.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; filter: grayscale(100%); animation: pulse 1.5s infinite ease-in-out; border: none !important; height: 40px !important; width: 40px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }
@keyframes pulse { 0% { transform: scale(0.95); opacity: 0.7; } 50% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.7; } }

/* --- 全局UI无边框设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: transparent !important; border: none !important; padding: 8px 0px !important; margin-bottom: 8px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: var(--input-bg) !important; border: 1px solid rgba(255, 255, 255, 0.1) !important; border-style: solid !important; color: var(--text-main) !important; border-radius: 4px !important; padding: 8px !important; }
input:focus, textarea:focus, select:focus { outline: 1px solid var(--accent-color) !important; }
.menu_button { background-color: var(--card-bg) !important; border: none !important; color: var(--text-main) !important; transition: all 0.2s ease; border-radius: 4px !important; }
.menu_button:hover { background-color: var(--accent-color) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-color) !important; }

/* 弹窗设计 */
dialog.popup { background-color: transparent !important; border: none !important; }
dialog.popup .popup-body, #dialogue_popup { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/0jlI/4578X2298/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D5064664199991360891%26skey%3D%40crypt_5a237c93_d042088f617635782c79a9e8ba4d1d73%26mmweb_appid%3Dwx_webfilehelper.jpg/webp') !important; background-size: cover !important; background-position: center !important; border: none !important; border-radius: var(--border-radius) !important; position: relative; overflow: hidden; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(10, 10, 10, 0.75); backdrop-filter: blur(5px); z-index: 0; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on { background-color: var(--selected-color) !important; color: #fff !important; }
#left-nav-panel .menu_button.selected { background-color: var(--selected-color) !important; color: #fff !important; }

/* 滑块设计 */
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none !important; appearance: none !important; width: 28px !important; height: 28px !important; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/izmZ/1963X2060/2026-03-04_172119.png/webp') !important; filter: grayscale(100%); background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; background-color: transparent !important; border: none !important; cursor: pointer !important; }
input[type="range"]::-moz-range-thumb { width: 28px !important; height: 28px !important; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260304/izmZ/1963X2060/2026-03-04_172119.png/webp') !important; filter: grayscale(100%); background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; background-color: transparent !important; border: none !important; cursor: pointer !important; }
.neo-range-slider { background: rgba(150, 150, 150, 0.3) !important; }

/* 楼层信息显示 */
.mes .mesIDDisplay { position: absolute; top: 40px !important; right: 20px !important; left: auto !important; transform: none !important; background: rgba(18, 18, 18, 0.9) !important; border: 1px solid rgba(139, 0, 0, 0.4) !important; border-style: solid !important; color: var(--accent-color) !important; font-size: 13px !important; backdrop-filter: blur(4px) !important; z-index: 100; padding: 4px 12px !important; white-space: nowrap; line-height: 1 !important; border-radius: 2px !important; font-family: var(--font-english); }
.mesIDDisplay::before { content: '加载序列 # '; color: #ccc; }
.mesIDDisplay::after { content: ' [COMPLETE]'; color: #ccc; }

/* --- 手机端适配 --- */
@media (max-width: 768px) {
    /* 启用并调整窗口模拟系统 */
    .mes { padding-top: 34px !important; }

    /* 调整标题栏和控件以适应小屏幕 */
    .mes::before { font-size: 12px; padding-left: 10px; letter-spacing: 1px; }
    .mes::after { font-size: 14px; right: 10px; letter-spacing: 5px; }

    /* 调整头像 */
    .mes .avatar { left: 20px; width: 80px !important; height: 80px !important; top: 80px; }

    /* 调整内容块和内部元素位置 */
    .mes .mes_block > .ch_name { left: 110px !important; right: 15px !important; top: 15px !important; }
    .mes .mes_block { padding: 30px 15px 45px 15px !important; /* 为底部警报留出空间 */ }

    /* 调整楼层信息位置，避免与窗口控件重叠 */
    .mes .mesIDDisplay {
        top: 40px !important;
        right: 15px !important;
        font-size: 11px !important;
        padding: 2px 6px !important;
    }

    /* 调整系统警报 */
    .mes .mes_block::before {
        font-size: 10px;
        padding: 2px 6px;
        bottom: 10px;
        right: 10px;
        white-space: nowrap;
    }
}

